from ekosistem import Ekosistem

class Rawa(Ekosistem):
    def __init__(self, nama, lokasi, tinggi_air_cm):
        super().__init__(nama, lokasi)
        self.tinggi_air_cm = tinggi_air_cm

    def status(self):
        if self.tinggi_air_cm >= 80:
            return "Siaga"
        return "Normal"
